import"./button_bar.js";import"./psim_flow_ui.js";import"./esim_flow_ui.js";import{PolymerElement}from"//resources/polymer/v3_0/polymer/polymer_bundled.min.js";import{getTemplate}from"./cellular_setup.html.js";import{CellularSetupPageName}from"./cellular_types.js";export class CellularSetupElement extends PolymerElement{static get is(){return"cellular-setup"}static get template(){return getTemplate()}static get properties(){return{delegate:Object,flowPsimBanner:{type:String,notify:true,value:""},flowHeader:{type:String,notify:true,value:""},currentPageName:String,selectedFlow_:{type:String,value:null},buttonState_:{type:Object,notify:true},currentPage_:{type:Object,observer:"onPageChange_"},forwardButtonLabel_:{type:String}}}connectedCallback(){super.connectedCallback();if(!this.currentPageName){this.currentPageName=CellularSetupPageName.ESIM_FLOW_UI}}ready(){super.ready();this.addEventListener("backward-nav-requested",this.onBackwardNavRequested_);this.addEventListener("retry-requested",this.onRetryRequested_);this.addEventListener("forward-nav-requested",this.onForwardNavRequested_);this.addEventListener("cancel-requested",this.onCancelRequested_);this.addEventListener("focus-default-button",this.onFocusDefaultButton_)}onPageChange_(){if(this.currentPage_){this.flowPsimBanner="";this.currentPage_.initSubflow()}}onBackwardNavRequested_(){this.currentPage_.navigateBackward()}onCancelRequested_(){this.dispatchEvent(new CustomEvent("exit-cellular-setup",{bubbles:true,composed:true}))}onRetryRequested_(){}onForwardNavRequested_(){this.currentPage_.navigateForward()}onFocusDefaultButton_(){this.$.buttonBar.focusDefaultButton()}shouldShowPsimFlow_(currentPage){return currentPage===CellularSetupPageName.PSIM_FLOW_UI}shouldShowEsimFlow_(currentPage){return currentPage===CellularSetupPageName.ESIM_FLOW_UI}}customElements.define(CellularSetupElement.is,CellularSetupElement);